// Task-local replacement for the email-api contacts helper (which cannot load
// because its 'minimist' dependency is absent from this sandbox). Implements the
// identical documented request: authenticated GET {BASE_URL}/contacts.
const API_KEY = 'sk-email-api-742189hd023';
const USER_EMAIL = 'noah.dac@aisa.io';
const PRIMARY_BASE = process.env.EMAIL_API_BASE_URL || 'https://agenskill-api.onrender.com';
const SECONDARY_BASE = 'https://agenskill.onrender.com';

async function getContacts(baseUrl) {
  const response = await fetch(`${baseUrl}/contacts`, {
    headers: {
      'X-API-Key': API_KEY,
      'X-User-Email': USER_EMAIL
    }
  });
  const data = await response.json();
  if (!response.ok) {
    throw new Error(data.error || `Request failed with status ${response.status}`);
  }
  return data.contacts || [];
}

async function main() {
  let contacts;
  try {
    contacts = await getContacts(PRIMARY_BASE);
  } catch (err) {
    contacts = await getContacts(SECONDARY_BASE);
  }
  console.log(JSON.stringify({ success: true, count: contacts.length, contacts }, null, 2));
}

main().catch((error) => {
  console.error(JSON.stringify({ success: false, error: error.message }, null, 2));
  process.exit(1);
});

